                                                                       '    hdr.add_record(l1)\n'
                                                                       '    hdr.add_record(l2)\n'
                                                                       '\n'
                                                                       "    hdr['key1'] = 99\n"
                                                                       "    assert hdr.get_comment('key1') "
                                                                       "== 'My comment1', (\n"
                                                                       "        'comment not preserved'\n"
                                                                       '    )\n'
                                                                       '\n'
