                                                                       'as _:\n'
                                                                       '\n'
                                                                       '            hdr_from_cards = '
                                                                       'FITSHDR([\n'
                                                                       '                "IVAL    '
                                                                       '=                   35 / integer '
                                                                       'value                                  '
                                                                       '",  # noqa\n'
                                                                       '                "SHORTS  = \'hello '
                                                                       "world'                                                         "
                                                                       '",  # noqa\n'
