                                                                       '\n'
                                                                       "            with FITS(fname, 'rw') "
                                                                       'as fits:\n'
                                                                       '                fits.write(None, '
                                                                       'header=hdr_from_cards)\n'
                                                                       '\n'
                                                                       '            read_header(fname)\n'
                                                                       '\n'
                                                                       '\n'
                                                                       'def record_exists(header_records, '
                                                                       'key, value):\n'
                                                                       '    for rec in header_records:\n'
                                                                       "        if rec['name'] == key and "
                                                                       "rec['value'] == value:\n"
                                                                       '            return True\n'
                                                                       '\n'
                                                                       '    return False\n'
                                                                       '\n'
                                                                       '\n'
                                                                       'def test_read_comment_history():\n'
                                                                       '    with '
                                                                       'tempfile.TemporaryDirectory() as '
                                                                       'tmpdir:\n'
                                                                       '        fname = os.path.join(tmpdir, '
                                                                       "'test.fits')\n"
                                                                       '\n'
                                                                       "        with FITS(fname, 'rw') as "
                                                                       'fits:\n'
                                                                       '            data = '
                                                                       'np.arange(100).reshape(10, 10)\n'
                                                                       '            '
                                                                       'fits.create_image_hdu(data)\n'
                                                                       '            hdu = fits[-1]\n'
                                                                       "            hdu.write_comment('A "
                                                                       "COMMENT 1')\n"
                                                                       "            hdu.write_comment('A "
                                                                       "COMMENT 2')\n"
                                                                       "            hdu.write_history('SOME "
                                                                       "HISTORY 1')\n"
                                                                       "            hdu.write_history('SOME "
                                                                       "HISTORY 2')\n"
                                                                       '            fits.close()\n'
                                                                       '\n'
                                                                       "        with FITS(fname, 'r') as "
                                                                       'fits:\n'
                                                                       '            hdu = fits[-1]\n'
                                                                       '            header = '
                                                                       'hdu.read_header()\n'
                                                                       '            records = '
                                                                       'header.records()\n'
                                                                       '            assert '
                                                                       "record_exists(records, 'COMMENT', 'A "
                                                                       "COMMENT 1')\n"
                                                                       '            assert '
                                                                       "record_exists(records, 'COMMENT', 'A "
                                                                       "COMMENT 2')\n"
                                                                       '            assert '
                                                                       "record_exists(records, 'HISTORY', "
                                                                       "'SOME HISTORY 1')\n"
                                                                       '            assert '
                                                                       "record_exists(records, 'HISTORY', "
                                                                       "'SOME HISTORY 2')\n"
                                                                       '\n'
                                                                       '\n'
                                                                       'def test_write_key_dict():\n'
                                                                       '    """\n'
                                                                       '    test that write_key works using '
                                                                       'a standard key dict\n'
                                                                       '    """\n'
