                                                                      "'test.fits')\n"
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            # note mixing up byte '
                                                                      'orders a bit\n'
                                                                      '            for dtype in DTYPES:\n'
                                                                      '                data = '
                                                                      'np.arange(5*20, '
                                                                      'dtype=dtype).reshape(5, 20)\n'
                                                                      "                header = {'DTYPE': "
                                                                      "dtype, 'NBYTES': "
                                                                      'data.dtype.itemsize}\n'
                                                                      '                '
                                                                      'fits.write_image(data, '
                                                                      'header=header)\n'
                                                                      '                rdata = '
                                                                      'fits[-1].read()\n'
                                                                      '\n'
                                                                      '                compare_array(data, '
                                                                      'rdata, "images")\n'
                                                                      '\n'
