                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            '
                                                                      'fits.create_table_hdu(data, '
                                                                      "extname='mytable')\n"
                                                                      '\n'
                                                                      '            d = {}\n'
