                                                                      "    vardata = adata['vardata']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            d = {}\n'
                                                                      '            for n in '
                                                                      'vardata.dtype.names:\n'
