                                                                      '\n'
                                                                      '            fits.write(d)\n'
                                                                      '\n'
                                                                      '        d = read(fname)\n'
                                                                      '        compare_rec_with_var(vardata, '
                                                                      'd, "dict of arrays, var")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def '
                                                                      'test_table_write_list_of_arrays_scratch():\n'
                                                                      '    """\n'
                                                                      '    This version creating the table '
                                                                      'from the names and list, creating\n'
                                                                      '    table first\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            names = [n for n in '
                                                                      'data.dtype.names]\n'
                                                                      '            dlist = [data[n] for n in '
                                                                      'data.dtype.names]\n'
                                                                      '            fits.write(dlist, '
                                                                      'names=names)\n'
                                                                      '\n'
                                                                      '        d = read(fname)\n'
                                                                      '        compare_rec(data, d, "list of '
                                                                      'arrays, scratch")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def '
                                                                      'test_table_write_list_of_arrays():\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            '
                                                                      'fits.create_table_hdu(data, '
                                                                      "extname='mytable')\n"
                                                                      '\n'
                                                                      '            columns = [n for n in '
                                                                      'data.dtype.names]\n'
                                                                      '            dlist = [data[n] for n in '
                                                                      'data.dtype.names]\n'
