                                                                      'columns=columns)\n'
                                                                      '\n'
                                                                      '        d = read(fname, '
                                                                      "ext='mytable')\n"
                                                                      '        compare_rec(data, d, "list of '
                                                                      'arrays")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def '
                                                                      'test_table_write_list_of_arrays_var():\n'
                                                                      '    """\n'
                                                                      '    This version creating the table '
                                                                      'from the names and list, variable\n'
                                                                      '    lenght cols\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    vardata = adata['vardata']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            names = [n for n in '
                                                                      'vardata.dtype.names]\n'
                                                                      '            dlist = [vardata[n] for n '
                                                                      'in vardata.dtype.names]\n'
                                                                      '            fits.write(dlist, '
                                                                      'names=names)\n'
                                                                      '\n'
                                                                      '        d = read(fname)\n'
                                                                      '        compare_rec_with_var(vardata, '
                                                                      'd, "list of arrays, var")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_write_bad_string():\n'
                                                                      '\n'
                                                                      "    for d in ['S0', 'U0']:\n"
                                                                      "        dt = [('s', d)]\n"
                                                                      '\n'
                                                                      "        # old numpy didn't allow this "
                                                                      'dtype, so will throw\n'
                                                                      '        # a TypeError for empty '
                                                                      'dtype\n'
                                                                      '        try:\n'
                                                                      '            data = np.zeros(1, '
                                                                      'dtype=dt)\n'
                                                                      '            supported = True\n'
                                                                      '        except TypeError:\n'
                                                                      '            supported = False\n'
                                                                      '\n'
                                                                      '        if supported:\n'
                                                                      '            with '
                                                                      'pytest.raises(ValueError):\n'
                                                                      '                with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '                    fname = '
                                                                      "os.path.join(tmpdir, 'test.fits')\n"
                                                                      '                    with FITS(fname, '
                                                                      "'rw') as fits:\n"
                                                                      '                        '
                                                                      'fits.write(data)\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_variable_length_columns():\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    vardata = adata['vardata']\n"
                                                                      '\n'
                                                                      "    for vstorage in ['fixed', "
                                                                      "'object']:\n"
                                                                      '        with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '            fname = '
                                                                      "os.path.join(tmpdir, 'test.fits')\n"
                                                                      '\n'
                                                                      "            with FITS(fname, 'rw', "
                                                                      'vstorage=vstorage) as fits:\n'
                                                                      '                fits.write(vardata)\n'
                                                                      '\n'
                                                                      '                # reading multiple '
                                                                      'columns\n'
                                                                      '                d = fits[1].read()\n'
                                                                      '                '
                                                                      'compare_rec_with_var(\n'
                                                                      '                    vardata, d, "read '
                                                                      'all test \'%s\'" % vstorage\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      "                cols = ['u2scalar', "
                                                                      "'Sobj']\n"
                                                                      '                d = '
                                                                      'fits[1].read(columns=cols)\n'
                                                                      '                '
                                                                      'compare_rec_with_var(\n'
                                                                      '                    vardata, d, "read '
                                                                      'all test subcols \'%s\'" % vstorage\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '                # one at a time\n'
                                                                      '                for f in '
                                                                      'vardata.dtype.names:\n'
                                                                      '                    d = '
                                                                      'fits[1].read_column(f)\n'
                                                                      '                    if '
                                                                      'util.is_object(vardata[f]):\n'
                                                                      '                        '
                                                                      'compare_object_array(\n'
                                                                      '                            '
                                                                      'vardata[f], d,\n'
                                                                      '                            "read all '
                                                                      'field \'%s\'" % f\n'
                                                                      '                        )\n'
                                                                      '\n'
                                                                      '                # same as above with '
                                                                      'slices\n'
                                                                      '                # reading multiple '
                                                                      'columns\n'
                                                                      '                d = fits[1][:]\n'
                                                                      '                '
                                                                      'compare_rec_with_var(\n'
                                                                      '                    vardata, d, "read '
                                                                      'all test \'%s\'" % vstorage\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '                d = fits[1][cols][:]\n'
                                                                      '                '
                                                                      'compare_rec_with_var(\n'
                                                                      '                    vardata, d, "read '
                                                                      'all test subcols \'%s\'" % vstorage\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '                # one at a time\n'
                                                                      '                for f in '
                                                                      'vardata.dtype.names:\n'
                                                                      '                    d = '
                                                                      'fits[1][f][:]\n'
                                                                      '                    if '
                                                                      'util.is_object(vardata[f]):\n'
                                                                      '                        '
                                                                      'compare_object_array(\n'
                                                                      '                            '
                                                                      'vardata[f], d,\n'
                                                                      '                            "read all '
                                                                      'field \'%s\'" % f\n'
                                                                      '                        )\n'
                                                                      '\n'
                                                                      '                #\n'
                                                                      '                # now same with sub '
                                                                      'rows\n'
                                                                      '                #\n'
                                                                      '\n'
                                                                      '                # reading multiple '
                                                                      'columns, sorted and unsorted\n'
                                                                      '                for rows in [[0, 2], '
                                                                      '[2, 0]]:\n'
                                                                      '                    d = '
                                                                      'fits[1].read(rows=rows)\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata, d, '
                                                                      '"read subrows test \'%s\'" % '
                                                                      'vstorage,\n'
                                                                      '                        rows=rows,\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1].read(columns=cols, '
                                                                      'rows=rows)\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata,\n'
                                                                      '                        d,\n'
                                                                      '                        "read subrows '
                                                                      'test subcols \'%s\'" % vstorage,\n'
                                                                      '                        rows=rows,\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    # one at a time\n'
                                                                      '                    for f in '
                                                                      'vardata.dtype.names:\n'
                                                                      '                        d = '
                                                                      'fits[1].read_column(f, rows=rows)\n'
                                                                      '                        if '
                                                                      'util.is_object(vardata[f]):\n'
                                                                      '                            '
                                                                      'compare_object_array(\n'
                                                                      '                                '
                                                                      'vardata[f], d,\n'
                                                                      '                                "read '
                                                                      'subrows field \'%s\'" % f,\n'
                                                                      '                                '
                                                                      'rows=rows,\n'
                                                                      '                            )\n'
                                                                      '\n'
                                                                      '                    # same as above '
                                                                      'with slices\n'
                                                                      '                    # reading '
                                                                      'multiple columns\n'
                                                                      '                    d = '
                                                                      'fits[1][rows]\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata, d, '
                                                                      '"read subrows slice test \'%s\'" % '
                                                                      'vstorage,\n'
                                                                      '                        rows=rows,\n'
                                                                      '                    )\n'
                                                                      '                    d = fits[1][2:4]\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata,\n'
                                                                      '                        d,\n'
                                                                      '                        "read slice '
                                                                      'test \'%s\'" % vstorage,\n'
                                                                      '                        rows=[2, 3],\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1][cols][rows]\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata,\n'
                                                                      '                        d,\n'
                                                                      '                        "read subcols '
                                                                      'subrows slice test \'%s\'" % '
                                                                      'vstorage,\n'
                                                                      '                        rows=rows,\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1][cols][2:4]\n'
                                                                      '\n'
                                                                      '                    '
                                                                      'compare_rec_with_var(\n'
                                                                      '                        vardata,\n'
                                                                      '                        d,\n'
                                                                      '                        "read subcols '
                                                                      'slice test \'%s\'" % vstorage,\n'
                                                                      '                        rows=[2, 3],\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    # one at a time\n'
                                                                      '                    for f in '
                                                                      'vardata.dtype.names:\n'
                                                                      '                        d = '
                                                                      'fits[1][f][rows]\n'
                                                                      '                        if '
                                                                      'util.is_object(vardata[f]):\n'
                                                                      '                            '
                                                                      'compare_object_array(\n'
                                                                      '                                '
                                                                      'vardata[f], d,\n'
                                                                      '                                "read '
                                                                      'subrows field \'%s\'" % f,\n'
                                                                      '                                '
                                                                      'rows=rows,\n'
                                                                      '                            )\n'
                                                                      '                        d = '
                                                                      'fits[1][f][2:4]\n'
                                                                      '                        if '
                                                                      'util.is_object(vardata[f]):\n'
                                                                      '                            '
                                                                      'compare_object_array(\n'
                                                                      '                                '
                                                                      'vardata[f], d,\n'
                                                                      '                                "read '
                                                                      'slice field \'%s\'" % f,\n'
                                                                      '                                '
                                                                      'rows=[2, 3],\n'
                                                                      '                            )\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_iter():\n'
                                                                      '    """\n'
                                                                      '    Test iterating over rows of a '
                                                                      'table\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits.write_table(\n'
                                                                      '                data,\n'
                                                                      '                '
                                                                      "header=adata['keys'],\n"
                                                                      "                extname='mytable'\n"
                                                                      '            )\n'
                                                                      '\n'
                                                                      '        # one row at a time\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '            hdu = fits["mytable"]\n'
                                                                      '            i = 0\n'
                                                                      '            for row_data in hdu:\n'
                                                                      '                compare_rec(data[i], '
                                                                      'row_data, "table data")\n'
                                                                      '                i += 1\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_ascii_table_write_read():\n'
                                                                      '    """\n'
                                                                      '    Test write and read for an ascii '
                                                                      'table\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    ascii_data = adata['ascii_data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            fits.write_table(\n'
                                                                      '                ascii_data,\n'
                                                                      "                table_type='ascii',\n"
                                                                      '                '
                                                                      "header=adata['keys'],\n"
                                                                      "                extname='mytable',\n"
                                                                      '            )\n'
                                                                      '\n'
                                                                      '            # cfitsio always reports '
                                                                      'type as i4 and f8, period, even if '
                                                                      'if\n'
                                                                      '            # written with higher '
                                                                      'precision.  Need to fix that somehow\n'
                                                                      '            for f in '
                                                                      'ascii_data.dtype.names:\n'
                                                                      '                d = '
                                                                      'fits[1].read_column(f)\n'
                                                                      '                if d.dtype == '
                                                                      'np.float64:\n'
                                                                      '                    # note we should '
                                                                      'be able to do 1.11e-16 in principle, '
                                                                      'but\n'
                                                                      '                    # in practice we '
                                                                      'get more like 2.15e-16\n'
                                                                      '                    '
                                                                      'compare_array_tol(\n'
                                                                      '                        '
                                                                      'ascii_data[f], d, 2.15e-16, "table '
                                                                      'field read \'%s\'" % f\n'
                                                                      '                    )\n'
                                                                      '                else:\n'
                                                                      '                    compare_array(\n'
                                                                      '                        '
                                                                      'ascii_data[f], d, "table field read '
                                                                      '\'%s\'" % f\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '            for rows in [[1, 3], [3, '
                                                                      '1]]:\n'
