                                                                      'rows=rows)\n'
                                                                      '                    for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                        d = data[f]\n'
                                                                      '                        if d.dtype == '
                                                                      'np.float64:\n'
                                                                      '                            '
                                                                      'compare_array_tol(ascii_data[f][rows], '
                                                                      'd, 2.15e-16,\n'
                                                                      '                                              '
                                                                      '"table subcol, \'%s\'" % f)\n'
                                                                      '                        else:\n'
                                                                      '                            '
                                                                      'compare_array(ascii_data[f][rows], '
                                                                      'd,\n'
                                                                      '                                          '
                                                                      '"table subcol, \'%s\'" % f)\n'
                                                                      '\n'
                                                                      '                    data = '
                                                                      'fits[1][cols][rows]\n'
                                                                      '                    for f in '
