                                                                      '\n'
                                                                      '        compare_data = data[[0, 2]]\n'
                                                                      '        compare_rec(compare_data, d, '
                                                                      '"delete rows")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_where():\n'
                                                                      '    """\n'
                                                                      '    Use the where method to get '
                                                                      'indices for a row filter expression\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data2 = adata['data2']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits.write_table(data2)\n'
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # get all indices\n'
                                                                      '        #\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      "            a = fits[1].where('x > 3 "
                                                                      "&& y < 8')\n"
                                                                      "        b = np.where((data2['x'] > 3) "
                                                                      "& (data2['y'] < 8))[0]\n"
                                                                      '        '
                                                                      'np.testing.assert_array_equal(a, b)\n'
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # get slice of indices\n'
                                                                      '        #\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      "            a = fits[1].where('x > 3 "
                                                                      "&& y < 8', 2, 8)\n"
                                                                      "        b = np.where((data2['x'][2:8] "
                                                                      "> 3) & (data2['y'][2:8] < 8))[0]\n"
                                                                      '        '
                                                                      'np.testing.assert_array_equal(a, b)\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_resize():\n'
                                                                      '    """\n'
                                                                      '    Use the resize method to change '
                                                                      'the size of a table\n'
                                                                      '\n'
                                                                      '    default values get filled in and '
                                                                      'these are tested\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # shrink from back\n'
                                                                      '        #\n'
                                                                      "        with FITS(fname, 'rw', "
                                                                      'clobber=True) as fits:\n'
                                                                      '            fits.write_table(data)\n'
                                                                      '\n'
                                                                      '        nrows = 2\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits[1].resize(nrows)\n'
                                                                      '\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '\n'
                                                                      '        compare_data = data[0:nrows]\n'
                                                                      '        compare_rec(compare_data, d, '
                                                                      '"shrink from back")\n'
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # shrink from front\n'
                                                                      '        #\n'
                                                                      "        with FITS(fname, 'rw', "
                                                                      'clobber=True) as fits:\n'
                                                                      '            fits.write_table(data)\n'
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits[1].resize(nrows, '
                                                                      'front=True)\n'
                                                                      '\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '\n'
                                                                      '        compare_data = '
                                                                      'data[nrows-data.size:]\n'
                                                                      '        compare_rec(compare_data, d, '
                                                                      '"shrink from front")\n'
                                                                      '\n'
                                                                      "        # These don't get zerod\n"
                                                                      '\n'
                                                                      '        nrows = 10\n'
                                                                      '        add_data = '
                                                                      'np.zeros(nrows-data.size, '
                                                                      'dtype=data.dtype)\n'
                                                                      "        add_data['i1scalar'] = -128\n"
                                                                      "        add_data['i1vec'] = -128\n"
                                                                      "        add_data['i1arr'] = -128\n"
                                                                      "        add_data['u2scalar'] = 32768\n"
                                                                      "        add_data['u2vec'] = 32768\n"
                                                                      "        add_data['u2arr'] = 32768\n"
                                                                      "        add_data['u4scalar'] = "
                                                                      '2147483648\n'
                                                                      "        add_data['u4vec'] = "
                                                                      '2147483648\n'
                                                                      "        add_data['u4arr'] = "
                                                                      '2147483648\n'
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # expand at the back\n'
                                                                      '        #\n'
                                                                      "        with FITS(fname, 'rw', "
                                                                      'clobber=True) as fits:\n'
                                                                      '            fits.write_table(data)\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits[1].resize(nrows)\n'
                                                                      '\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '\n'
                                                                      '        compare_data = '
                                                                      'np.hstack((data, add_data))\n'
                                                                      '        compare_rec(compare_data, d, '
                                                                      '"expand at the back")\n'
                                                                      '\n'
                                                                      '        #\n'
                                                                      '        # expand at the front\n'
                                                                      '        #\n'
                                                                      "        with FITS(fname, 'rw', "
                                                                      'clobber=True) as fits:\n'
                                                                      '            fits.write_table(data)\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits[1].resize(nrows, '
                                                                      'front=True)\n'
                                                                      '\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '\n'
                                                                      '        compare_data = '
                                                                      'np.hstack((add_data, data))\n'
                                                                      "        # These don't get zerod\n"
                                                                      '        compare_rec(compare_data, d, '
                                                                      '"expand at the front")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_slice():\n'
                                                                      '    """\n'
                                                                      '    Test reading by slice\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            # initial write\n'
                                                                      '            fits.write_table(data)\n'
                                                                      '\n'
                                                                      '            # test reading single '
                                                                      'columns\n'
                                                                      '            for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                d = fits[1][f][:]\n'
                                                                      '                compare_array(\n'
                                                                      '                    data[f], d, "test '
                                                                      'read all rows %s column subset" % f\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '            # test reading row '
                                                                      'subsets\n'
                                                                      '            rows = [1, 3]\n'
                                                                      '            for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                d = fits[1][f][rows]\n'
                                                                      '                '
                                                                      'compare_array(data[f][rows], d, "test '
                                                                      '%s row subset" % f)\n'
                                                                      '            for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                d = fits[1][f][1:3]\n'
                                                                      '                '
                                                                      'compare_array(data[f][1:3], d, "test '
                                                                      '%s row slice" % f)\n'
                                                                      '            for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                d = '
                                                                      'fits[1][f][1:4:2]\n'
                                                                      '                compare_array(\n'
                                                                      '                    data[f][1:4:2], '
                                                                      'd, "test %s row slice with step" % f\n'
                                                                      '                )\n'
                                                                      '            for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                d = fits[1][f][::2]\n'
                                                                      '                compare_array(\n'
                                                                      '                    data[f][::2], d, '
                                                                      '"test %s row slice with only setp" % '
                                                                      'f\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '            # now list of columns\n'
                                                                      "            cols = ['u2scalar', "
                                                                      "'f4vec', 'Sarr']\n"
                                                                      '            d = fits[1][cols][:]\n'
                                                                      '            for f in d.dtype.names:\n'
                                                                      '                '
                                                                      'compare_array(data[f][:], d[f], "test '
                                                                      'column list %s" % f)\n'
                                                                      '\n'
                                                                      "            cols = ['u2scalar', "
                                                                      "'f4vec', 'Sarr']\n"
                                                                      '            d = fits[1][cols][rows]\n'
                                                                      '            for f in d.dtype.names:\n'
                                                                      '                compare_array(\n'
                                                                      '                    data[f][rows], '
                                                                      'd[f], "test column list %s row '
                                                                      'subset" % f\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      "            cols = ['u2scalar', "
                                                                      "'f4vec', 'Sarr']\n"
                                                                      '            d = fits[1][cols][1:3]\n'
                                                                      '            for f in d.dtype.names:\n'
                                                                      '                compare_array(\n'
                                                                      '                    data[f][1:3], '
                                                                      'd[f], "test column list %s row slice" '
                                                                      '% f\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_append():\n'
                                                                      '    """\n'
                                                                      '    Test creating a table and '
                                                                      'appending new rows.\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            # initial write\n'
                                                                      '            fits.write_table(data, '
                                                                      "header=adata['keys'], "
                                                                      "extname='mytable')\n"
                                                                      '            # now append\n'
                                                                      '            data2 = data.copy()\n'
                                                                      "            data2['f4scalar'] = 3\n"
                                                                      '            fits[1].append(data2)\n'
                                                                      '\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '            assert d.size == '
                                                                      'data.size*2\n'
                                                                      '\n'
                                                                      '            compare_rec(data, '
                                                                      'd[0:data.size], "Comparing initial '
                                                                      'write")\n'
                                                                      '            compare_rec(data2, '
                                                                      'd[data.size:], "Comparing appended '
                                                                      'data")\n'
                                                                      '\n'
                                                                      '            h = '
                                                                      'fits[1].read_header()\n'
                                                                      '            '
                                                                      "compare_headerlist_header(adata['keys'], "
                                                                      'h)\n'
                                                                      '\n'
                                                                      '            # append with list of '
                                                                      'arrays and names\n'
                                                                      '            names = data.dtype.names\n'
                                                                      '            data3 = '
                                                                      '[np.array(data[name]) for name in '
                                                                      'names]\n'
                                                                      '            fits[1].append(data3, '
                                                                      'names=names)\n'
                                                                      '\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '            assert d.size == '
                                                                      'data.size*3\n'
                                                                      '            compare_rec(data, '
                                                                      'd[2*data.size:], "Comparing appended '
                                                                      'data")\n'
                                                                      '\n'
                                                                      '            # append with list of '
                                                                      'arrays and columns\n'
                                                                      '            fits[1].append(data3, '
                                                                      'columns=names)\n'
                                                                      '\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '            assert d.size == '
                                                                      'data.size*4\n'
                                                                      '            compare_rec(data, '
                                                                      'd[3*data.size:], "Comparing appended '
                                                                      'data")\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_subsets():\n'
                                                                      '    """\n'
                                                                      '    testing reading subsets\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            fits.write_table(data, '
                                                                      "header=adata['keys'], "
                                                                      "extname='mytable')\n"
                                                                      '\n'
                                                                      '            for rows in [[1, 3], [3, '
                                                                      '1]]:\n'
                                                                      '                d = '
                                                                      'fits[1].read(rows=rows)\n'
                                                                      '                '
                                                                      'compare_rec_subrows(data, d, rows, '
                                                                      '"table subset")\n'
                                                                      '                columns = '
                                                                      "['i1scalar', 'f4arr']\n"
                                                                      '                d = '
                                                                      'fits[1].read(columns=columns, '
                                                                      'rows=rows)\n'
                                                                      '\n'
                                                                      '                for f in columns:\n'
                                                                      '                    d = '
                                                                      'fits[1].read_column(f, rows=rows)\n'
                                                                      '                    compare_array(\n'
                                                                      '                        '
                                                                      'data[f][rows], d, "row subset, '
                                                                      'multi-column \'%s\'" % f\n'
                                                                      '                    )\n'
                                                                      '                for f in '
                                                                      'data.dtype.names:\n'
                                                                      '                    d = '
                                                                      'fits[1].read_column(f, rows=rows)\n'
                                                                      '                    compare_array(\n'
                                                                      '                        '
                                                                      'data[f][rows], d, "row subset, column '
                                                                      '\'%s\'" % f\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_gz_write_read():\n'
                                                                      '    """\n'
                                                                      '    Test a basic table write, data '
                                                                      'and a header, then reading back in '
                                                                      'to\n'
                                                                      '    check the values\n'
                                                                      '\n'
                                                                      '    this code all works, but the file '
                                                                      'is zere size when done!\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            fits.write_table(data, '
                                                                      "header=adata['keys'], "
                                                                      "extname='mytable')\n"
                                                                      '\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '            compare_rec(data, d, '
                                                                      '"gzip write/read")\n'
                                                                      '\n'
                                                                      '            h = '
                                                                      'fits[1].read_header()\n'
                                                                      '            for entry in '
                                                                      "adata['keys']:\n"
                                                                      '                name = '
                                                                      "entry['name'].upper()\n"
                                                                      '                value = '
                                                                      "entry['value']\n"
                                                                      '                hvalue = h[name]\n'
                                                                      '                if isinstance(hvalue, '
                                                                      'str):\n'
                                                                      '                    hvalue = '
                                                                      'hvalue.strip()\n'
                                                                      '                assert value == '
                                                                      'hvalue, "testing header key \'%s\'" % '
                                                                      'name\n'
                                                                      '\n'
                                                                      "                if 'comment' in "
                                                                      'entry:\n'
                                                                      '                    assert (\n'
                                                                      '                        '
                                                                      "entry['comment'].strip()\n"
                                                                      '                        == '
                                                                      'h.get_comment(name).strip()\n'
                                                                      '                    ), (\n'
                                                                      '                        "testing '
                                                                      'comment for header key \'%s\'" % '
                                                                      'name\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '        stat = os.stat(fname)\n'
                                                                      '        assert stat.st_size != 0, '
                                                                      '"Making sure the data was flushed to '
                                                                      'disk"\n'
                                                                      '\n'
                                                                      '\n'
                                                                      "@pytest.mark.skipif('SKIP_BZIP_TEST' "
                                                                      'in os.environ,\n'
                                                                      '                    '
                                                                      "reason='SKIP_BZIP_TEST set')\n"
                                                                      'def test_bz2_read():\n'
                                                                      "    '''\n"
                                                                      '    Write a normal .fits file, run '
                                                                      'bzip2 on it, then read the bz2\n'
                                                                      "    file and verify that it's the "
                                                                      "same as what we put in; we don't\n"
                                                                      '    [currently support or] test '
                                                                      '*writing* bzip2.\n'
                                                                      "    '''\n"
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        bzfname = fname + '.bz2'\n"
                                                                      '\n'
                                                                      '        try:\n'
                                                                      "            fits = FITS(fname, 'rw')\n"
                                                                      '            fits.write_table(data, '
                                                                      "header=adata['keys'], "
                                                                      "extname='mytable')\n"
                                                                      '            fits.close()\n'
                                                                      '\n'
                                                                      "            os.system('bzip2 %s' % "
                                                                      'fname)\n'
                                                                      '            f2 = FITS(bzfname)\n'
                                                                      '            d = f2[1].read()\n'
                                                                      '            compare_rec(data, d, '
                                                                      '"bzip2 read")\n'
                                                                      '\n'
                                                                      '            h = f2[1].read_header()\n'
                                                                      '            for entry in '
                                                                      "adata['keys']:\n"
                                                                      '                name = '
                                                                      "entry['name'].upper()\n"
                                                                      '                value = '
                                                                      "entry['value']\n"
                                                                      '                hvalue = h[name]\n'
                                                                      '                if isinstance(hvalue, '
                                                                      'str):\n'
                                                                      '                    hvalue = '
                                                                      'hvalue.strip()\n'
                                                                      '\n'
                                                                      '                assert value == '
                                                                      'hvalue, "testing header key \'%s\'" % '
                                                                      'name\n'
                                                                      '\n'
                                                                      "                if 'comment' in "
                                                                      'entry:\n'
                                                                      '                    assert (\n'
                                                                      '                        '
                                                                      "entry['comment'].strip()\n"
                                                                      '                        == '
                                                                      'h.get_comment(name).strip()\n'
                                                                      '                    ), (\n'
                                                                      '                        "testing '
                                                                      'comment for header key \'%s\'" % '
                                                                      'name\n'
                                                                      '                    )\n'
                                                                      '        except Exception:\n'
                                                                      '            import traceback\n'
                                                                      '            traceback.print_exc()\n'
                                                                      '\n'
                                                                      "            assert False, 'Exception "
                                                                      "in testing bzip2 reading'\n"
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_checksum():\n'
                                                                      '    """\n'
                                                                      '    test that checksumming works\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    data = adata['data']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            fits.write_table(data, '
                                                                      "header=adata['keys'], "
                                                                      "extname='mytable')\n"
                                                                      '            fits[1].write_checksum()\n'
                                                                      '            '
                                                                      'fits[1].verify_checksum()\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_trim_strings():\n'
                                                                      '    """\n'
                                                                      '    test mode where we strim strings '
                                                                      'on read\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      "    dt = [('fval', 'f8'), ('name', "
                                                                      "'S15'), ('vec', 'f4', 2)]\n"
                                                                      '    n = 3\n'
                                                                      '    data = np.zeros(n, dtype=dt)\n'
                                                                      "    data['fval'] = "
                                                                      'np.random.random(n)\n'
                                                                      "    data['vec'] = "
                                                                      'np.random.random(n*2).reshape(n, 2)\n'
                                                                      '\n'
                                                                      "    data['name'] = ['mike', "
                                                                      "'really_long_name_to_fill', 'jan']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits.write(data)\n'
                                                                      '\n'
                                                                      '        for onconstruct in [True, '
                                                                      'False]:\n'
                                                                      '            if onconstruct:\n'
                                                                      '                ctrim = True\n'
                                                                      '                otrim = False\n'
                                                                      '            else:\n'
                                                                      '                ctrim = False\n'
                                                                      '                otrim = True\n'
                                                                      '\n'
                                                                      "            with FITS(fname, 'rw', "
                                                                      'trim_strings=ctrim) as fits:\n'
                                                                      '\n'
                                                                      '                if ctrim:\n'
                                                                      '                    dread = '
                                                                      'fits[1][:]\n'
                                                                      '                    compare_rec(\n'
                                                                      '                        data,\n'
                                                                      '                        dread,\n'
                                                                      '                        "trimmed '
                                                                      'strings constructor",\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                    dname = '
                                                                      "fits[1]['name'][:]\n"
                                                                      '                    compare_array(\n'
                                                                      '                        '
                                                                      "data['name'],\n"
                                                                      '                        dname,\n'
                                                                      '                        "trimmed '
                                                                      'strings col read, constructor",\n'
                                                                      '                    )\n'
                                                                      '                    dread = '
                                                                      "fits[1][['name']][:]\n"
                                                                      '                    compare_array(\n'
                                                                      '                        '
                                                                      "data['name'],\n"
                                                                      '                        '
                                                                      "dread['name'],\n"
                                                                      '                        "trimmed '
                                                                      'strings col read, constructor",\n'
                                                                      '                    )\n'
                                                                      '\n'
                                                                      '                dread = '
                                                                      'fits[1].read(trim_strings=otrim)\n'
                                                                      '                compare_rec(\n'
                                                                      '                    data,\n'
                                                                      '                    dread,\n'
                                                                      '                    "trimmed strings '
                                                                      'keyword",\n'
                                                                      '                )\n'
                                                                      '                dname = '
                                                                      "fits[1].read(columns='name', "
                                                                      'trim_strings=otrim)\n'
                                                                      '                compare_array(\n'
                                                                      "                    data['name'],\n"
                                                                      '                    dname,\n'
                                                                      '                    "trimmed strings '
                                                                      'col keyword",\n'
                                                                      '                )\n'
                                                                      '                dread = '
                                                                      "fits[1].read(columns=['name'], "
                                                                      'trim_strings=otrim)\n'
                                                                      '                compare_array(\n'
                                                                      "                    data['name'],\n"
                                                                      "                    dread['name'],\n"
                                                                      '                    "trimmed strings '
                                                                      'col keyword",\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '        # convenience function\n'
                                                                      '        dread = read(fname, '
                                                                      'trim_strings=True)\n'
                                                                      '        compare_rec(\n'
                                                                      '            data,\n'
                                                                      '            dread,\n'
                                                                      '            "trimmed strings '
                                                                      'convenience function",\n'
                                                                      '        )\n'
                                                                      '        dname = read(fname, '
                                                                      "columns='name', trim_strings=True)\n"
                                                                      '        compare_array(\n'
                                                                      "            data['name'],\n"
                                                                      '            dname,\n'
                                                                      '            "trimmed strings col '
                                                                      'convenience function",\n'
                                                                      '        )\n'
                                                                      '        dread = read(fname, '
                                                                      "columns=['name'], trim_strings=True)\n"
                                                                      '        compare_array(\n'
                                                                      "            data['name'],\n"
                                                                      "            dread['name'],\n"
                                                                      '            "trimmed strings col '
                                                                      'convenience function",\n'
                                                                      '        )\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_lower_upper():\n'
                                                                      '    """\n'
                                                                      '    test forcing names to upper and '
                                                                      'lower\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    rng = '
                                                                      'np.random.RandomState(8908)\n'
                                                                      '\n'
                                                                      "    dt = [('MyName', 'f8'), "
                                                                      "('StuffThings', 'i4'), ('Blah', "
                                                                      "'f4')]\n"
                                                                      '    data = np.zeros(3, dtype=dt)\n'
                                                                      "    data['MyName'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      "    data['StuffThings'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      "    data['Blah'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits.write(data)\n'
                                                                      '\n'
                                                                      '        for i in [1, 2]:\n'
                                                                      '            if i == 1:\n'
                                                                      '                lower = True\n'
                                                                      '                upper = False\n'
                                                                      '            else:\n'
                                                                      '                lower = False\n'
                                                                      '                upper = True\n'
                                                                      '\n'
                                                                      "            with FITS(fname, 'rw', "
                                                                      'lower=lower, upper=upper) as fits:\n'
                                                                      '                for rows in [None, '
                                                                      '[1, 2]]:\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1].read(rows=rows)\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names,\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1].read(\n'
                                                                      '                        rows=rows, '
                                                                      "columns=['MyName', 'stuffthings']\n"
                                                                      '                    )\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names[0:2],\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                    d = fits[1][1:2]\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names,\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                    if rows is not '
                                                                      'None:\n'
                                                                      '                        d = '
                                                                      'fits[1][rows]\n'
                                                                      '                    else:\n'
                                                                      '                        d = '
                                                                      'fits[1][:]\n'
                                                                      '\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names,\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                    if rows is not '
                                                                      'None:\n'
                                                                      '                        d = '
                                                                      "fits[1][['myname', "
                                                                      "'stuffthings']][rows]\n"
                                                                      '                    else:\n'
                                                                      '                        d = '
                                                                      "fits[1][['myname', "
                                                                      "'stuffthings']][:]\n"
                                                                      '\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names[0:2],\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '            # using overrides\n'
                                                                      "            with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '                for rows in [None, '
                                                                      '[1, 2]]:\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1].read(rows=rows, lower=lower, '
                                                                      'upper=upper)\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names,\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                    d = '
                                                                      'fits[1].read(\n'
                                                                      '                        rows=rows, '
                                                                      "columns=['MyName', 'stuffthings'],\n"
                                                                      '                        lower=lower, '
                                                                      'upper=upper\n'
                                                                      '                    )\n'
                                                                      '                    '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names[0:2],\n'
                                                                      '                                  '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '            for rows in [None, [1, '
                                                                      '2]]:\n'
                                                                      '                d = read(fname, '
                                                                      'rows=rows, lower=lower, upper=upper)\n'
                                                                      '                '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names,\n'
                                                                      '                              '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '                d = read(fname, '
                                                                      "rows=rows, columns=['MyName', "
                                                                      "'stuffthings'],\n"
                                                                      '                         lower=lower, '
                                                                      'upper=upper)\n'
                                                                      '                '
                                                                      'compare_names(d.dtype.names, '
                                                                      'data.dtype.names[0:2],\n'
                                                                      '                              '
                                                                      'lower=lower, upper=upper)\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_read_raw():\n'
                                                                      '    """\n'
                                                                      '    testing reading the file as raw '
                                                                      'bytes\n'
                                                                      '    """\n'
                                                                      '    rng = '
                                                                      'np.random.RandomState(8908)\n'
                                                                      '\n'
                                                                      "    dt = [('MyName', 'f8'), "
                                                                      "('StuffThings', 'i4'), ('Blah', "
                                                                      "'f4')]\n"
                                                                      '    data = np.zeros(3, dtype=dt)\n'
                                                                      "    data['MyName'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      "    data['StuffThings'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      "    data['Blah'] = "
                                                                      'rng.uniform(data.size)\n'
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      '        try:\n'
                                                                      "            with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '                fits.write(data)\n'
                                                                      '                raw1 = '
                                                                      'fits.read_raw()\n'
                                                                      '\n'
                                                                      "            with FITS('mem://', 'rw') "
                                                                      'as fits:\n'
                                                                      '                fits.write(data)\n'
                                                                      '                raw2 = '
                                                                      'fits.read_raw()\n'
                                                                      '\n'
                                                                      "            with open(fname, 'rb') as "
                                                                      'fobj:\n'
                                                                      '                raw3 = fobj.read()\n'
                                                                      '\n'
                                                                      '            assert raw1 == raw2\n'
                                                                      '            assert raw1 == raw3\n'
                                                                      '        except Exception:\n'
                                                                      '            import traceback\n'
                                                                      '            traceback.print_exc()\n'
                                                                      "            assert False, 'Exception "
                                                                      "in testing read_raw'\n"
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_bitcol_read_write():\n'
                                                                      '    """\n'
                                                                      '    Test basic write/read with '
                                                                      'bitcols\n'
                                                                      '    """\n'
                                                                      '\n'
                                                                      '    adata = make_data()\n'
                                                                      "    bdata = adata['bdata']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            fits.write_table(bdata, '
                                                                      "extname='mytable', "
                                                                      'write_bitcols=True)\n'
                                                                      '\n'
                                                                      '            d = fits[1].read()\n'
                                                                      '            compare_rec(bdata, d, '
                                                                      '"table read/write")\n'
                                                                      '\n'
                                                                      '        # now test read_column\n'
                                                                      '        with FITS(fname) as fits:\n'
                                                                      '\n'
                                                                      '            for f in '
                                                                      'bdata.dtype.names:\n'
                                                                      '                d = '
                                                                      'fits[1].read_column(f)\n'
                                                                      '                compare_array(\n'
                                                                      '                    bdata[f], d, '
                                                                      '"table 1 single field read \'%s\'" % '
                                                                      'f\n'
                                                                      '                )\n'
                                                                      '\n'
                                                                      '            # now list of columns\n'
                                                                      "            for cols in [['b1vec', "
                                                                      "'b1arr']]:\n"
                                                                      '                d = '
                                                                      'fits[1].read(columns=cols)\n'
                                                                      '                for f in '
                                                                      'd.dtype.names:\n'
                                                                      '                    '
                                                                      'compare_array(bdata[f][:], d[f], '
                                                                      '"test column list %s" % f)\n'
                                                                      '\n'
                                                                      '                for rows in [[1, 3], '
                                                                      '[3, 1]]:\n'
                                                                      '                    d = '
                                                                      'fits[1].read(columns=cols, '
                                                                      'rows=rows)\n'
                                                                      '                    for f in '
                                                                      'd.dtype.names:\n'
                                                                      '                        '
                                                                      'compare_array(\n'
                                                                      '                            '
                                                                      'bdata[f][rows],\n'
                                                                      '                            d[f],\n'
                                                                      '                            "test '
                                                                      'column list %s row subset" % f\n'
                                                                      '                        )\n'
                                                                      '\n'
                                                                      '\n'
                                                                      'def test_table_bitcol_append():\n'
                                                                      '    """\n'
                                                                      '    Test creating a table with bitcol '
                                                                      'support and appending new rows.\n'
                                                                      '    """\n'
                                                                      '    adata = make_data()\n'
                                                                      "    bdata = adata['bdata']\n"
                                                                      '\n'
                                                                      '    with '
                                                                      'tempfile.TemporaryDirectory() as '
                                                                      'tmpdir:\n'
                                                                      '        fname = os.path.join(tmpdir, '
                                                                      "'test.fits')\n"
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '\n'
                                                                      '            # initial write\n'
                                                                      '            fits.write_table(bdata, '
                                                                      "extname='mytable', "
                                                                      'write_bitcols=True)\n'
                                                                      '\n'
                                                                      "        with FITS(fname, 'rw') as "
                                                                      'fits:\n'
                                                                      '            # now append\n'
                                                                      '            bdata2 = bdata.copy()\n'
                                                                      '            fits[1].append(bdata2)\n'
                                                                      '\n'
